using System;using System.Collections;using System.Collections.Generic;using System.Data;using System.Data.Common;using System.IO;using System.Reflection;using System.Runtime.Serialization;using System.Windows.Forms;
class AccessorySelectionRegression{
 const BindingFlags F=BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic;static Assembly app;static Type repo;static int checks;
 static object Field(object o,string n){return o.GetType().GetField(n,F).GetValue(o);}static object Get(object o,string n){return o.GetType().GetProperty(n,F).GetValue(o,null);}static void Set(object o,string n,object v){o.GetType().GetProperty(n,F).SetValue(o,v,null);}static object Call(object o,string n,params object[]a){try{return o.GetType().GetMethod(n,F).Invoke(o,a);}catch(TargetInvocationException e){throw e.InnerException;}}static void Check(bool b,string m){if(!b)throw new Exception(m);checks++;}static HashSet<long> Ids(DataTable t){var set=new HashSet<long>();foreach(DataRow r in t.Rows)set.Add(Convert.ToInt64(r["SeqNo"]));return set;}
 static DataTable Prices(){var t=new DataTable();t.Columns.Add("SeqNo",typeof(long));foreach(var n in new[]{"CustCode","PriceCategory","CategoryName","PriceItemName","SpecText","UnitName","BillingBasis","ItemType"})t.Columns.Add(n);t.Columns.Add("CurrentUnitPrice",typeof(decimal));t.Columns.Add("Material").DefaultValue="부품";return t;}
 static void Add(DataTable t,long id,string customer,string spec,object price){t.Rows.Add(id,(object)customer??DBNull.Value,"수성","현수막","부자재",spec,"개","수량","MATERIAL",price);}
 static void Unit(){var t=Prices();Add(t,1,null,"A",100m);Add(t,2,"C1","A",80m);Add(t,3,"OTHER","A",10m);Add(t,4,null,"B",200m);Add(t,5,null,"다른 규격",300m);Add(t,6,"C1","B",DBNull.Value);Add(t,7,"C1","전용 품목",70m);Add(t,8,"C1","A",90m);var select=repo.GetMethod("SelectAccessoryPrices",BindingFlags.Static|BindingFlags.NonPublic);foreach(var test in new[]{new object[]{null,new long[]{1,4,5}},new object[]{"C1",new long[]{2,4,5,7,8}},new object[]{"OTHER",new long[]{3,4,5}},new object[]{"NO_RATE",new long[]{1,4,5}}}){using(var result=(DataTable)select.Invoke(null,new object[]{t,test[0]})){Check(Ids(result).SetEquals((long[])test[1]),"Customer priority, fallback, variant and other-customer exclusion");}}
 }
 static DataTable Query(string category,string sub,string text,string customer){return (DataTable)repo.GetMethod("GetAccessoryPriceItems").Invoke(null,new object[]{category,sub,text,customer});}
 static void Live(){var basic=Query(null,null,null,null);Check(basic.Rows.Count>0,"Parts/components catalog available without prerequisites");using(var connection=(DbConnection)app.GetType("PineTree.Classes.DB").GetMethod("CreateConnection").Invoke(null,null)){connection.Open();using(var command=connection.CreateCommand()){command.CommandText="SELECT SeqNo FROM PriceItems WHERE IsActive=1 AND TRIM(Material) IN ('부품','구성품') AND (CustCode IS NULL OR TRIM(CustCode)='')";using(var reader=command.ExecuteReader()){var expected=new DataTable();expected.Load(reader);Check(Ids(basic).SetEquals(Ids(expected)),"Material criterion replaces ItemType criterion exactly");}}}foreach(DataRow row in basic.Rows){Check(new HashSet<string>{"부품","구성품"}.Contains(Convert.ToString(row["Material"]).Trim()),"Only parts and components included");Check(string.IsNullOrWhiteSpace(Convert.ToString(row["CustCode"])),"No customer uses only base prices");}
 var categories=new HashSet<string>();foreach(DataRow r in basic.Rows)categories.Add(Convert.ToString(r["PriceCategory"]));foreach(string category in categories){using(var rows=Query(category,null,null,null)){foreach(DataRow r in rows.Rows)Check(Convert.ToString(r["PriceCategory"])==category,"Category filter exact");}}
 using(var dialog=(Form)Activator.CreateInstance(app.GetType("PineTree.Dialogs.DialogPriceItemList"),new object[]{"",null,"",null})){var combo=Field(dialog,"cbCategory");Check((bool)Get(combo,"Enabled")&&(int)Get(combo,"SelectedIndex")==0,"All categories available and editable");var grid=Field(dialog,"FGrid1");Check(Ids((DataTable)Get(grid,"DataSource")).SetEquals(Ids(basic)),"Picker displays all parts and components without a customer");foreach(string category in categories){Call(dialog,"SelectComboItem",combo,category);var data=(DataTable)Get(grid,"DataSource");foreach(DataRow r in data.Rows)Check(Convert.ToString(r["PriceCategory"])==category,"Picker filters categories including ampersand names");}Call(dialog,"SelectComboItem",combo,"[전체]");Call(dialog,"LoadPriceItems");Check(Ids((DataTable)Get(grid,"DataSource")).SetEquals(Ids(basic)),"Search reload preserves material filter");}
 foreach(string name in new[]{"PineTree.UserControls.UcOrderDesignPad","PineTree.Dialogs.DialogOrderDesignPad"}){var type=app.GetType(name);using(var pad=(Control)FormatterServices.GetUninitializedObject(type)){(type.BaseType==typeof(Form)?typeof(Form):typeof(UserControl)).GetConstructor(Type.EmptyTypes).Invoke(pad,new object[0]);Call(pad,"InitializeComponent");Call(pad,"InitOrderItemTable");Call(pad,"InitOrderEditor");Call(pad,"InitPreviewEvent");bool picked=false;Exception failure=null;using(var timer=new Timer{Interval=25}){timer.Tick+=delegate{foreach(Form d in Application.OpenForms){if(d.GetType().Name!="DialogPriceItemList")continue;timer.Stop();try{Check((bool)Field(d,"_accessoriesOnly"),"Plus opens accessory mode");Set(Field(d,"FGrid1"),"Row",1);Call(d,"ConfirmSelectedPriceItem");picked=true;}catch(Exception ex){failure=ex;d.Close();}break;}};timer.Start();Call(pad,"ShowPriceItemListDialog","");timer.Stop();}if(failure!=null)throw failure;Check(picked && ((DataTable)Field(pad,"m_orderItems")).Rows.Count==1,"Plus adds accessory without customer or equipment category");}}
 using(var c=(DbConnection)app.GetType("PineTree.Classes.DB").GetMethod("CreateConnection").Invoke(null,null)){c.Open();using(var q=c.CreateCommand()){q.CommandText="SELECT DISTINCT CustCode FROM PriceItems WHERE IsActive=1 AND TRIM(Material) IN ('부품','구성품') AND CustCode IS NOT NULL AND TRIM(CustCode)<>'' LIMIT 5";var owners=new List<string>();using(var r=q.ExecuteReader())while(r.Read())owners.Add(Convert.ToString(r[0]));foreach(var owner in owners)using(var prices=Query(null,null,null,owner)){foreach(DataRow r in prices.Rows){var cust=Convert.ToString(r["CustCode"]);Check(string.IsNullOrWhiteSpace(cust)||cust.Trim()==owner.Trim(),"Live dedicated query excludes other customers");}}}}
 }
 [STAThread]static int Main(string[]args){try{Application.EnableVisualStyles();app=Assembly.LoadFrom(Path.GetFullPath(args[0]));repo=app.GetType("PineTree.Classes.PriceItemRepository");Unit();if(args.Length>1)Live();Console.WriteLine("PASS: "+checks+" accessory selection and customer-price checks");return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}}
}
